from pathlib import Path
import re
for f in sorted(Path('outputs').glob('*')):
 root=f.read_text().split('\\n')[0]
 stones={a+b:c for c,v in re.findall(r'A([BW])((?:\\[[a-s]{2}\\])+)',root) for a,b in re.findall(r'\\[(.)(.)\\]',v)}
 def ns(p):
  x,y=map(ord,p)
  return [chr(a)+chr(b) for a,b in [(x-1,y),(x+1,y),(x,y-1),(x,y+1)] if 97<=min(a,b) and max(a,b)<=115]
 seen=set(); outer=[]
 for p,c in stones.items():
  if p in seen:continue
  g={p};stack=[p];libs=set()
  while stack:
   for q in ns(stack.pop()):
    if q not in stones:libs.add(q)
    elif stones[q]==c and q not in g:g.add(q);stack.append(q)
  seen |= g
  if not libs: print('ILLEGAL SETUP',f,p)
  outer.append((c,len(g),min(g),''.join(sorted(libs)) if len(libs)<3 else len(libs)))
 print(f.name,outer)
PY"

